let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const headers = { "content-type": "application/json" };
const unchanged = () => [
  { id: input.fromId, balance: input.fromBalance, version: input.fromVersion },
  { id: input.toId, balance: input.toBalance, version: input.toVersion }
];

function respond(status, body, accounts, committed, messages, ordering, failures, retryability, extra = {}) {
  console.log(JSON.stringify({
    http: { status, headers, body, ...extra },
    database: { accounts, transaction: { committed } },
    messages,
    ordering,
    failures,
    retryability
  }));
}

const prior = input.existingTransfer ?? input.replay ?? input.idempotentResult;
const { amount } = input;

if (prior && typeof prior === "object") {
  const body = prior.body ?? prior;
  respond(200, body, unchanged(), false, [], ["idempotency.lookup", "replay.return"], [], false, { replayed: true });
} else if (input.replayed === true || input.idempotencyHit === true) {
  const body = { transferId: input.transferId, fromBalance: input.fromBalance, toBalance: input.toBalance };
  respond(200, body, unchanged(), false, [], ["idempotency.lookup", "replay.return"], [], false, { replayed: true });
} else if (!Number.isFinite(amount) || amount <= 0) {
  respond(400, { error: "invalid_amount" }, unchanged(), false, [], ["validate"], ["invalid_amount"], false);
} else if (
  (input.expectedFromVersion !== undefined && input.expectedFromVersion !== input.fromVersion) ||
  (input.expectedToVersion !== undefined && input.expectedToVersion !== input.toVersion) ||
  input.versionConflict === true
) {
  respond(409, { error: "version_conflict" }, unchanged(), false, [], ["idempotency.lookup", "version.check", "transaction.rollback"], ["version_conflict"], true);
} else if (input.fromBalance < amount) {
  respond(422, { error: "insufficient_funds" }, unchanged(), false, [], ["idempotency.lookup", "balance.check", "transaction.rollback"], ["insufficient_funds"], false);
} else {
  const fromBalance = input.fromBalance - amount;
  const toBalance = input.toBalance + amount;
  const fromVersion = input.fromVersion + 1;
  const toVersion = input.toVersion + 1;
  respond(
    201,
    { transferId: input.transferId, fromBalance, toBalance, fromVersion, toVersion },
    [
      { id: input.fromId, balance: fromBalance, version: fromVersion },
      { id: input.toId, balance: toBalance, version: toVersion }
    ],
    true,
    [{ type: "transfer.completed", transferId: input.transferId, fromId: input.fromId, toId: input.toId, amount }],
    ["idempotency.lookup", "version.check", "balance.check", "accounts.update", "transaction.commit", "event.emit"],
    [],
    false
  );
}

